//! Generated by `cargo xtask generate`; operation graphs live in `mod.rs`.
use super::*;
use crate::primitive::{self, dispatch};
use archmage::ScalarToken;

#[archmage::attune(
    _v4x_t(cfg(avx512)),
    _v4_t(cfg(avx512)),
    _v3_t,
    _neon_t,
    _wasm128_t,
    _scalar_t
)]
fn kernel_f32x4<const O: u32, const OP: bool>(
    t: Token,
    args: [f32; 4],
) -> Result<[f32; 4], PrimitiveError> {
    use magetypes::simd::generic::f32x4;
    graph4::<O, OP, _>(t, f32x4::from_array_t(t, args)).map(|v| v.to_array())
}

#[inline(always)]
fn auto_f32x4<const O: u32, const OP: bool>(args: [f32; 4]) -> Result<[f32; 4], PrimitiveError> {
    dispatch!(
        primitive::select(O & RecipOptions::CALLER != 0),
        O,
        OP,
        args,
        kernel_f32x4_v3_t,
        kernel_f32x4_v4_t,
        kernel_f32x4_v4x_t,
        kernel_f32x4_neon_t,
        kernel_f32x4_wasm128_t,
        kernel_f32x4_scalar_t
    )
}

/// Configured recip retaining the caller's 4-lane proof; no autonomous upgrade.
#[inline(always)]
pub fn try_recip_f32x4_with<const O: u32, T: magetypes::simd::backends::F32x4Convert>(
    t: T,
    x: magetypes::simd::generic::f32x4<T>,
) -> Result<magetypes::simd::generic::f32x4<T>, PrimitiveError> {
    graph4::<O, false, T>(t, x)
}

/// Scalar tail using this exact vector width and proof. Invalid scalar masks contain bit zero only.
#[inline(always)]
pub fn try_recip_f32x4_lane_with<const O: u32, T: magetypes::simd::backends::F32x4Convert>(
    t: T,
    x: f32,
) -> Result<f32, PrimitiveError> {
    use magetypes::simd::generic::f32x4 as V;
    try_recip_f32x4_with::<O, T>(t, V::splat_t(t, x))
        .map(|v| v.to_array()[0])
        .map_err(|e| PrimitiveError {
            lane_mask: e.lane_mask & 1,
            ..e
        })
}

