/// Configured array recip, selecting once; widths 1, 4, 8, and enabled 16.
#[inline(always)]
pub fn try_recip_array_with<const O: u32, const N: usize>(
    x: [f32; N],
) -> Result<[f32; N], PrimitiveError> {
    const {
        assert!(RecipOptions::valid(O), "invalid primitive options");
    }
    let mut out = [0.0; N];
    if N == 1 {
        let result =
            auto_f32x4::<O, false>(core::array::from_fn(|i| x[if N == 1 { 0 } else { i }]))
                .map_err(|e| PrimitiveError {
                    lane_mask: if N == 1 { e.lane_mask & 1 } else { e.lane_mask },
                    ..e
                })?;
        out.copy_from_slice(&result[..N]);
        return Ok(out);
    }
    if N == 4 {
        let result =
            auto_f32x4::<O, false>(core::array::from_fn(|i| x[if N == 1 { 0 } else { i }]))
                .map_err(|e| PrimitiveError {
                    lane_mask: if N == 1 { e.lane_mask & 1 } else { e.lane_mask },
                    ..e
                })?;
        out.copy_from_slice(&result[..N]);
        return Ok(out);
    }
    if N == 8 {
        let result =
            auto_f32x8::<O, false>(core::array::from_fn(|i| x[if N == 1 { 0 } else { i }]))
                .map_err(|e| PrimitiveError {
                    lane_mask: if N == 1 { e.lane_mask & 1 } else { e.lane_mask },
                    ..e
                })?;
        out.copy_from_slice(&result[..N]);
        return Ok(out);
    }
    #[cfg(feature = "w512")]
    if N == 16 {
        let result =
            auto_f32x16::<O, false>(core::array::from_fn(|i| x[if N == 1 { 0 } else { i }]))
                .map_err(|e| PrimitiveError {
                    lane_mask: if N == 1 { e.lane_mask & 1 } else { e.lane_mask },
                    ..e
                })?;
        out.copy_from_slice(&result[..N]);
        return Ok(out);
    }
    Err(PrimitiveError {
        kind: PrimitiveErrorKind::UnsupportedWidth,
        lane_mask: 0,
    })
}

/// Configured scalar recip. Approximate graphs select one provider for the whole operation; HIGHP needs no CPU detection.
#[inline(always)]
pub fn try_recip_with<const O: u32>(x: f32) -> Result<f32, PrimitiveError> {
    if O & 6 == 0 {
        try_recip_f32x4_lane_with::<O, _>(ScalarToken, x)
    } else {
        try_recip_array_with::<O, 1>([x]).map(|v| v[0])
    }
}

